 $proposalSteps = ['Viewed by client' => $report['recorded_viewed_count'], 'Client responded' => $report['recorded_response_count'], 'Interviews' => $report['recorded_interview_count'], 'Hired' => $report['recorded_hired_count']];
 $proposalTotal = max(1, $report['proposals_manually_marked_submitted']);
 $stageMax = max([1, ...array_values((array) $report['lead_stages'])]);
 $colors = ['#564dcc','#218cbb','#11a88b','#e8a33a','#8458bc','#d47862','#49a8aa'];
 $sequences = $report['followup_sequences_current'];
 $won = max(0, (int) $report['deals_won']); $lost = max(0, (int) $report['deals_lost']); $closed = $won + $lost;
 $pie = '<svg xmlns="http://www.w3.org/2000/svg" width="150" height="150" viewBox="0 0 150 150">';
 if ($closed === 0) { $pie .= '<circle cx="75" cy="75" r="66" fill="#e6efed"/>'; }
 elseif ($won === 0 || $lost === 0) { $pie .= '<circle cx="75" cy="75" r="66" fill="'.($won ? '#14a686' : '#e29a42').'"/>'; }
 else { $angle = 2 * M_PI * $won / $closed; $x = 75 + 66 * sin($angle); $y = 75 - 66 * cos($angle); $large = $angle > M_PI ? 1 : 0; $pie .= '<circle cx="75" cy="75" r="66" fill="#e29a42"/><path d="M 75 75 L 75 9 A 66 66 0 '.$large.' 1 '.round($x,3).' '.round($y,3).' Z" fill="#14a686"/>'; }
 $pie .= '<circle cx="75" cy="75" r="42" fill="#ffffff"/><circle cx="75" cy="75" r="65" fill="none" stroke="#ffffff" stroke-width="2"/></svg>'; $pieImage = 'data:image/svg+xml;base64,'.base64_encode($pie);
 $done = max(0, (int) $sequences['completed']); $overdue = min(max(0, (int) $sequences['overdue']), max(0, (int) $sequences['in_progress'])); $active = max(0, (int) $sequences['in_progress'] - $overdue); $sequenceTotal = $done + $active + $overdue;
 $stages = (array) $report['lead_stages']; $n = count($stages); $funnel = '<svg xmlns="http://www.w3.org/2000/svg" width="240" height="'.max(1,$n*30).'" viewBox="0 0 240 '.max(1,$n*30).'">';
 foreach (array_values($stages) as $i => $count) { $top = $n > 1 ? 220 - 110*$i/$n : 220; $bottom = $n > 1 ? 220 - 110*($i+1)/$n : 170; $y = $i*30; $funnel .= '<polygon points="'.round((240-$top)/2,2).','.$y.' '.round((240+$top)/2,2).','.$y.' '.round((240+$bottom)/2,2).','.($y+28).' '.round((240-$bottom)/2,2).','.($y+28).'" fill="'.$colors[$i % count($colors)].'" stroke="#ffffff" stroke-width="1"/>'; }
 $funnel .= '</svg>'; $funnelImage = 'data:image/svg+xml;base64,'.base64_encode($funnel);
